import fs from "fs";
import { createRequire } from "module";
import path from "path";
import { fileURLToPath } from "url";
const AGENT_NATIVE_PACKAGE_PREFIX = "@agent-native/";
function readPackageManifest(manifestPath) {
    try {
        const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
        return manifest && typeof manifest === "object"
            ? manifest
            : null;
    }
    catch {
        // coercion-ok: missing or malformed manifests are typed absence from the optional version inventory.
        return null;
    }
}
function dependencyNames(manifest, includeDevDependencies = false) {
    if (!manifest) {
        return [];
    }
    return [
        ...Object.keys(manifest.dependencies ?? {}),
        ...Object.keys(manifest.optionalDependencies ?? {}),
        ...Object.keys(manifest.peerDependencies ?? {}),
        ...(includeDevDependencies
            ? Object.keys(manifest.devDependencies ?? {})
            : []),
    ];
}
function resolvePackageManifest(packageName, resolutionBase) {
    let entryPath;
    const packageRequire = createRequire(path.join(resolutionBase, "package.json"));
    try {
        entryPath = packageRequire.resolve(packageName);
    }
    catch {
        if (packageName !== "@agent-native/core") {
            return null;
        }
        const coreManifestPath = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../package.json");
        const coreManifest = readPackageManifest(coreManifestPath);
        return coreManifest?.name === packageName
            ? { manifest: coreManifest, manifestPath: coreManifestPath }
            : null;
    }
    let directory = path.dirname(entryPath);
    for (let depth = 0; depth < 20; depth += 1) {
        const manifestPath = path.join(directory, "package.json");
        const manifest = readPackageManifest(manifestPath);
        if (manifest?.name === packageName) {
            return { manifest, manifestPath };
        }
        const parent = path.dirname(directory);
        if (parent === directory) {
            break;
        }
        directory = parent;
    }
    return null;
}
export function resolveAgentNativePackageVersions(cwd) {
    const appManifest = readPackageManifest(path.join(cwd, "package.json"));
    const packageNames = new Set([
        "@agent-native/core",
        ...dependencyNames(appManifest, true).filter((name) => name.startsWith(AGENT_NATIVE_PACKAGE_PREFIX)),
    ]);
    const resolvedVersions = new Map();
    const queuedPackages = [...packageNames].map((packageName) => ({
        packageName,
        resolutionBase: cwd,
    }));
    while (queuedPackages.length > 0) {
        const queuedPackage = queuedPackages.shift();
        if (!queuedPackage)
            continue;
        const resolvedPackage = resolvePackageManifest(queuedPackage.packageName, queuedPackage.resolutionBase);
        if (!resolvedPackage) {
            continue;
        }
        const { manifest } = resolvedPackage;
        if (typeof manifest.version === "string" && manifest.version.trim()) {
            resolvedVersions.set(queuedPackage.packageName, manifest.version.trim());
        }
        for (const dependencyName of dependencyNames(manifest)) {
            if (dependencyName.startsWith(AGENT_NATIVE_PACKAGE_PREFIX) &&
                !packageNames.has(dependencyName)) {
                packageNames.add(dependencyName);
                queuedPackages.push({
                    packageName: dependencyName,
                    resolutionBase: path.dirname(resolvedPackage.manifestPath),
                });
            }
        }
    }
    return Object.fromEntries([...resolvedVersions.entries()].sort(([left], [right]) => left.localeCompare(right)));
}
